ON CONFLICT (id) DO UPDATE SET
  latin_phrase        = EXCLUDED.latin_phrase,
  indonesian_meaning  = EXCLUDED.indonesian_meaning,
  literal_translation = EXCLUDED.literal_translation,
  pronunciation_guide = EXCLUDED.pronunciation_guide,
  legal_fields        = EXCLUDED.legal_fields,
  legal_meaning       = CASE
    WHEN public.maxims.status IN ('draft') THEN EXCLUDED.legal_meaning
    ELSE public.maxims.legal_meaning
  END,
  history             = CASE
    WHEN public.maxims.status IN ('draft') THEN EXCLUDED.history
    ELSE public.maxims.history
  END,
  data                = CASE
    WHEN public.maxims.status IN ('draft') THEN EXCLUDED.data
    ELSE public.maxims.data
  END,
  status              = CASE
    WHEN public.maxims.status = 'draft' THEN EXCLUDED.status
    ELSE public.maxims.status
  END,
  updated_at          = CASE
    WHEN public.maxims.status IN ('draft') THEN now()
    ELSE public.maxims.updated_at
  END;
